   819  static unsigned char *decode_chars(const unsigned char *src,
   820                                     unsigned char *dst, size_t cnt_in)
   821  {
   822      uint32_t value = 0;
   823      for (int i = 0; i < cnt_in; i++)
   824          value |= (uint32_t) ((src[i] - 33u) & 63) << 6 * (3 - i);
   825
   826      *dst++ = value >> 16;
   827      if (cnt_in >= 3)
   828          *dst++ = value >> 8 & 0xff;
   829      if (cnt_in >= 4)
   830          *dst++ = value & 0xff;
   831      return dst;
   832  }
